package io.github.cttir.qupflowr.protocol;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.util.Objects;
import java.util.Properties;

/**
 * Versions recorded at build time in {@code bridge-build.properties} (generated by Gradle).
 *
 * @param bridgeVersion version of the bridge implementation, e.g. {@code 0.1.0-SNAPSHOT}
 * @param protocolVersion protocol version declared by the build
 * @param qupathVersion QuPath version the bridge was compiled and tested against
 */
public record BuildInfo(String bridgeVersion, String protocolVersion, String qupathVersion) {

    /** Class path location of the generated properties file. */
    public static final String RESOURCE =
            "/io/github/cttir/qupflowr/protocol/bridge-build.properties";

    private static final class Holder {
        private static final BuildInfo INSTANCE = load();
    }

    /**
     * Creates build information.
     *
     * @param bridgeVersion bridge version
     * @param protocolVersion protocol version
     * @param qupathVersion QuPath version
     */
    public BuildInfo {
        Objects.requireNonNull(bridgeVersion, "bridgeVersion");
        Objects.requireNonNull(protocolVersion, "protocolVersion");
        Objects.requireNonNull(qupathVersion, "qupathVersion");
    }

    /**
     * Returns the build information bundled with these classes.
     *
     * @return build information
     * @throws IllegalStateException if the generated resource is missing or incomplete
     */
    public static BuildInfo current() {
        return Holder.INSTANCE;
    }

    private static BuildInfo load() {
        try (InputStream in = BuildInfo.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                throw new IllegalStateException("Missing build resource " + RESOURCE);
            }
            Properties properties = new Properties();
            properties.load(in);
            return new BuildInfo(
                    required(properties, "bridge_version"),
                    required(properties, "protocol_version"),
                    required(properties, "qupath_version"));
        } catch (IOException e) {
            throw new UncheckedIOException("Unable to read " + RESOURCE, e);
        }
    }

    private static String required(Properties properties, String key) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            throw new IllegalStateException("Build resource " + RESOURCE + " lacks " + key);
        }
        return value.strip();
    }
}
